    (F : bvmap 5 word) fc (m : mem) (c : pcore) (pad7 pad2 : list byte),
  rw_cells rsegs m P (ParserCoreCells c pad7 pad2) -> pc_state c = 0 -> pcore_ok c ->
  rw_cells rsegs m (P + 456) (ErrCodeCells EC_clear) ->
  stk rsegs m lo P -> 0xb4000 <= lo -> lo + 64 <= P -> P + 480 <= 2^64 -> mem_inv rsegs m ->
  evt rsegs (fun ms' => exists m',
           ms' = sro_call_ms P gp tp t0 t1 t2 a4 a5 a6 a7 (wz 0) s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m'
        /\ munch [(lo, P); (P + 456, P + 480)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
        /\ stk rsegs m' lo (P + -64)
        /\ rw_cells rsegs m' (P + -64) (map C8 [s6; s5; s4; s3; wz u64max; wz D; wz N; ra])
        /\ rw_cells rsegs m' P (ParserCoreCells c pad7 pad2)
        /\ rw_cells rsegs m' (P + 456) (ErrCodeCells EC_clear))
    (MS (mkR ra (Z_to_bv 64 P) gp tp t0 t1 t2 (wz N) (wz D) (wz (P + 352)) (wz (P + 408)) (wz P) (wz (P + 456)) a4 a5 a6 a7
             (wz u64max) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_SYNC_READ_OP) fc None m (seg_rom rsegs)).
