Section SR.
  Variable H : hsr.
  Hypothesis HH : heap_sr_hyps H.

(* [comment removed for export] *)
Lemma RWm_frame : forall (C : rsc) (w : rsw) (E E' : ecv) (m m' : mem) (hi : Z),
  rs_static C -> RWp H C w -> RWm H C w E m ->
  munch [(c_lo C, hi); (c_P C + 456, c_P C + 480)]%Z m m' -> wmono rsegs m m' -> mem_inv rsegs m' ->
  hi <= c_P C -> rw_cells rsegs m' (c_P C + 456) (ErrCodeCells E') ->
  RWm H C w E' m'.
Proof.
  intros C w E E' m m' hi STC RP RM MU1 WM1 MI1 HI EC1.
  destruct C as [P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s10 s11 F fc].
  destruct w as [d PB FBB FB fds Fs sds nr]. destruct d as [c S L ns ls em h u es insz g rdi LBn st errv].
  unfold RWm, rs_static in *. cbn_w_all.
  destruct STC as (P0 & PBB & BHI & AL16 & CEIL & IMG & LO & NR26 & (p7 & INS) & RBS & INA & TP).
  destruct RM as (PC & UW & RDI & J13 & J32a & J8a & J32b & J8b & HC & FTS & MV & FBU & EC & BS & SB & HP & ERR & AUX & MI).
  unfold RWp in RP. cbn_w_all.
  destruct RP as (PCOK & OWN & MOWN & HOWN & EH & ESH & _).
  assert (LOP : lo + 13136 <= P) by (clear - LO; unfold SRO_STACK, PUT_STACK, IPF_STACK, IPF_FRAME, OTF_STACK, INS_STACK, ROPNEW_STACK, RMALLOC_STACK in LO; lia).
  pose proof (FlatBuf_shape _ _ _ _ _ FBU) as (FS1 & FS2 & FS3 & FS4 & FS5).
  pose proof UW as (FC & HDR & USED & MB & RD & MRG & CBH & CBB & PFT & FI & XS).
  pose proof RBS as (RB1 & RB2 & RB3 & RB4 & RB5). unfold SZ_SPCI_STATE in RB4, RB5.
  assert (DJW : forall A0 k0, hi <= A0 -> (A0 + k0 <= P + 456 \/ P + 480 <= A0) -> disjoint_from [(lo, hi); (P + 456, P + 480)]%Z A0 k0).
  { intros A0 k0 K1 K2. cbn. clear - K1 K2. lia. }
  assert (DJH : forall A0 k0, A0 + k0 <= hceil -> disjoint_from [(lo, hi); (P + 456, P + 480)]%Z A0 k0).
  { intros A0 k0 K1. cbn. clear - K1 HI LOP CEIL. lia. }
  split; [eapply rw_cells_transport; [exact PC | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split.
  { unfold PutUw. cbn_w.
    split. { eapply FieldsC_transport_hi; [exact FC | exact MU1 | exact WM1 |]. clear - HI LOP CEIL.
             constructor; [cbn [fst snd]; lia|]. constructor; [cbn [fst snd]; lia|]. constructor. }
    split; [eapply rw_cells_transport; [exact HDR | exact MU1 | exact WM1 | apply DJW; unfold O_PR_HDR; cbn; clear - HI; lia]|].
    split; [eapply rw_cells_transport; [exact USED | exact MU1 | exact WM1 | apply DJW; unfold O_PR_USED; cbn; clear - HI; lia]|].
    split. { eapply MBuf_transport_gen; [exact MB | exact MU1 | exact WM1 | apply DJW; clear - HI; lia |].
             intros x sz IN. destruct (ESH x sz IN) as (K1 & K2 & K3). apply DJH; clear - K2; lia. }
    split; [eapply rw_cells_transport; [exact RD | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
    split; [eapply rw_cells_transport; [exact MRG | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
    split; [eapply rw_cells_transport; [exact CBH | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
    split; [eapply rw_cells_transport; [exact CBB | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
    split; [eapply PfTab_transport; [exact PFT | exact MU1 | exact WM1 | unfold PF_TABPTR; clear - HI LOP IMG; repeat constructor; cbn; lia]|].
    split; [eapply FTInit_transport; [exact FI | exact MU1 | unfold P_FT_INIT; cbn; clear - HI LOP IMG; lia]|].
    eapply XStatics_transport; [exact XS | exact MU1 | exact WM1 |]. clear - HI LOP IMG. repeat constructor; cbn; lia. }
  split; [eapply rw_cells_transport; [exact RDI | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split; [eapply rw_cells_transport; [exact J13 | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split; [eapply rw_cells_transport; [exact J32a | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split; [eapply rw_cells_transport; [exact J8a | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split; [eapply rw_cells_transport; [exact J32b | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split; [eapply rw_cells_transport; [exact J8b | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split. { eapply HttpCat_transport; [exact HC | exact MU1 | exact WM1 | clear - HI LOP IMG; unfold G_HTTP_CAT; cbn; lia | clear - HI LOP IMG; unfold G_HTTP_CAT_GUARD; cbn; lia]. }
  split; [eapply FTState_transport; [exact FTS | exact MU1 | exact WM1 | unfold G_FIELD_TABLE; cbn; clear - HI LOP IMG; lia]|].
  split; [unfold MiscVt48 in MV |- *; eapply ro_cells_transport; [exact MV | exact MU1 | unfold VP_MISC_ECAT; cbn; clear - HI LOP IMG; lia]|].
  split. { eapply FlatBuf_transport; [exact FBU | exact MU1 | exact WM1 | apply DJW; unfold SZ_FB; clear - HI; lia |].
           intros NE. apply DJH. unfold fb_cap. clear - FS4; lia. }
  split; [exact EC1|].
  split; [eapply rw_cells_transport; [exact BS | exact MU1 | exact WM1 | apply DJW; cbn; clear - HI; lia]|].
  split. { eapply StateBlock_transport; [exact SB | exact MU1 | exact WM1 | apply DJH; exact RB4 |].
           cbn [st_fb]. intros NEs.
           pose proof SB as (pS & j7S & j16S & j4S & _ & _ & _ & _ & _ & _ & _ & _ & FBs & _).
           pose proof (FlatBuf_shape _ _ _ _ _ FBs) as (SS1 & SS2 & SS3 & SS4 & SS5). cbn [st_fb] in SS4. unfold fb_cap. apply DJH. clear - SS4; lia. }
  split. { eapply (hh_RHEAP_frame H HH); [exact HP | exact MU1 | exact WM1 |].
           unfold rclient_write_ok. clear - HI LOP IMG CEIL. constructor; [left; cbn; lia|]. constructor; [left; cbn; lia|]. constructor. }
  split; [eapply rw_cells_transport; [exact ERR | exact MU1 | exact WM1 | unfold RERRNO; cbn; clear - HI LOP IMG; lia]|].
  split; [eapply (hh_rauxv_frame H HH); [exact AUX | exact MU1 | exact WM1 | unfold RAUXV_CELL; clear - HI LOP IMG PBB BHI; repeat constructor; cbn; lia] | exact MI1].
Qed.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition sro_at_call (C : rsc) (fr0 : list word) (s7 s8 s9 : word) (w : rsw) (cf : config) : Prop :=
  exists (t0 t1 t2 a4 a5 a6 a7 s4x t3 t4 t5 t6 : word) (m : mem) (E : ecv),
    cfg_ms cf = sro_call_ms (c_P C) (c_gp C) (c_tp C) t0 t1 t2 a4 a5 a6 a7 s4x s7 s8 s9 (c_s10 C) (c_s11 C) t3 t4 t5 t6 (c_F C) (c_fc C) m
    /\ pc_state (ps_c (w_d w)) <> 11
    /\ hs_KREL H (ps_st (w_d w)) (cfg_model cf) /\ hs_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWm H C w E m /\ RWp H C w
    /\ stk rsegs m (c_lo C) (c_P C + -64) /\ rw_cells rsegs m (c_P C + -64) (map C8 fr0) /\ length fr0 = 8%nat
    /\ xpres (c_LBin C) (c_P C) (sro_X (c_P C) (c_stb C)) (c_m0 C) m
    /\ w_nr w <= c_N C - zlength (w_sds w).

(* [comment removed for export] *)
Definition sro_ret (C : rsc) (rae s0e s1e s2e s3e s4e s5e s6e s7 s8 s9 : word) (cf : config) : Prop :=
  exists (t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (w : rsw) (E : ecv),
    cfg_ms cf = MS (mkR rae (Z_to_bv 64 (c_P C)) (c_gp C) (c_tp C) t0 t1 t2 s0e s1e a0 a1 a2 a3 a4 a5 a6 a7 s2e s3e s4e s5e s6e s7 s8 s9 (c_s10 C) (c_s11 C) t3 t4 t5 t6)
                   (c_F C) (ret_pc rae) (c_fc C) None m (seg_rom rsegs)
    /\ hs_KREL H (ps_st (w_d w)) (cfg_model cf) /\ hs_MPRES H (c_mo0 C) (cfg_model cf)
    /\ RWm H C w E m /\ RWp H C w /\ stk rsegs m (c_lo C) (c_P C)
    /\ xpres (c_LBin C) (c_P C) (sro_X (c_P C) (c_stb C)) (c_m0 C) m.

(* [comment removed for export] *)
Lemma sro_loop : forall (n : nat) (C : rsc) (rae s0e s1e s2e s3e s4e s5e s6e s7 s8 s9 : word) (w : rsw) (cf : config),
  rs_static C -> wM (c_N C) w < Z.of_nat n ->
  sro_at_call C [s6e; s5e; s4e; s3e; s2e; s1e; s0e; rae] s7 s8 s9 w cf ->
  hs_SR H (sro_ret C rae s0e s1e s2e s3e s4e s5e s6e s7 s8 s9) cf.
Proof.
  induction n as [|n IH]; intros C rae s0e s1e s2e s3e s4e s5e s6e s7 s8 s9 w cf STC LT AT.
  - exfalso. destruct STC as (_ & _ & _ & _ & _ & _ & _ & NR26 & _). unfold wM in LT. clear - LT NR26. unfold zlength in LT. cbn in LT. nia.
  - pose proof STC as STC0.
    destruct C as [P N lo B stb implb A LBin pad7 pad2 j13 j32a j8a j32b j8b mb m0 mo0 gp tp s10 s11 F fc].
